#include <cstdio>
#include <cstdlib>
#include <vector>

typedef std::vector<unsigned> Big; // little-endian, base 1e9

static Big add(const Big& x, const Big& y) {
    Big r;
    unsigned long long carry = 0;
    for (size_t i = 0; i < x.size() || i < y.size() || carry; ++i) {
        unsigned long long s = carry;
        if (i < x.size()) s += x[i];
        if (i < y.size()) s += y[i];
        r.push_back((unsigned)(s % 1000000000ULL));
        carry = s / 1000000000ULL;
    }
    return r;
}

int main(int argc, char** argv) {
    long n = argc > 1 ? std::strtol(argv[1], 0, 10) : 0;
    Big a(1, 1), b(1, 1);
    for (long i = 0; i < n; ++i) {
        Big c = add(a, b);
        a = b;
        b = c;
    }
    std::printf("%u", a.back());
    for (size_t i = a.size() - 1; i-- > 0;) std::printf("%09u", a[i]);
    std::printf("\n");
    return 0;
}
